def is_greater_than_or_equal(X1_cdf, X2_cdf, all_x_values):
    for x in all_x_values:
        if X1_cdf.get_value(x) > X2_cdf.get_value(x):
            return False
    return True

class PET_Distribution:
    def __init__(self, values_and_probabilities):
        # values_and_probabilities is a list of (execution_time, probability) tuples
        self.distribution = values_and_probabilities

    def get_probability(self, execution_time):
        # Returns P(execution_time = execution_time)
        for val, prob in self.distribution:
            if val == execution_time:
                return prob
        return 0.0

class PWCET_Distribution(PET_Distribution):
    def is_safe_pwcet(self, job_pet_distributions):
        # self is C_i, job_pet_distributions are C_j_i
        for pet_dist in job_pet_distributions:
            if not is_greater_than_or_equal(self.get_cdf(), pet_dist.get_cdf(), all_x_values):
                return False
        return True

