class PIT_Distribution:
    def __init__(self, values_and_probabilities):
        # values_and_probabilities is a list of (inter_arrival_time, probability) tuples
        self.distribution = values_and_probabilities

    def get_probability(self, inter_arrival_time):
        # Returns P(inter_arrival_time = inter_arrival_time)
        for val, prob in self.distribution:
            if val == inter_arrival_time:
                return prob
        return 0.0

class PMIT_Distribution(PIT_Distribution):
    def is_safe_pmit(self, job_pit_distributions):
        # self is T_i, job_pit_distributions are T_j_i
        for pit_dist in job_pit_distributions:
            # Note the reversal: T_j_i >= T_i means pit_dist.cdf <= self.cdf
            if not is_greater_than_or_equal(pit_dist.get_cdf(), self.get_cdf(), all_x_values):
                return False
        return True

