def calculate_dmp(R_i_j_dist, D_i_dist):
    dmp = 0.0
    # R_i_j_dist and D_i_dist are lists of (value, probability) tuples
    for r_val, r_prob in R_i_j_dist:
        for d_val, d_prob in D_i_dist:
            if r_val > d_val:
                dmp += r_prob * d_prob
    return dmp
